const prepare = function prepareFeedback(inputs) {
  const root = inputs.response;
  const response = root?.form_response ?? root;
  if (!response || typeof response !== "object" || Array.isArray(response))
    throw new Error("Expected a completed Typeform response.");
  if (!Array.isArray(response.answers) || !Array.isArray(response.definition?.fields))
    throw new Error("The Typeform response must include answer and field definitions.");
  const requiredTitles = [inputs.feedbackTitle, inputs.nameTitle].filter(Boolean);
  const fields = new Map();
  for (const field of response.definition.fields) {
    if (typeof field?.id !== "string" || typeof field.title !== "string") continue;
    const title = field.title.trim();
    if (!requiredTitles.includes(title)) continue;
    if (fields.has(title))
      throw new Error("Required Typeform question titles must be unique: " + title);
    fields.set(title, field.id);
  }
  const readText = (title) => {
    const id = fields.get(title);
    if (!id) throw new Error("Missing Typeform question: " + title);
    const answers = response.answers.filter((answer) => answer?.field?.id === id);
    if (
      answers.length !== 1 ||
      answers[0].type !== "text" ||
      typeof answers[0].text !== "string" ||
      !answers[0].text.trim()
    )
      throw new Error("Expected one nonempty text answer for: " + title);
    return answers[0].text;
  };
  const feedback = readText(inputs.feedbackTitle);
  const name = inputs.nameTitle ? readText(inputs.nameTitle) : "";
  return {
    feedback,
    name,
    request: { document: { type: "PLAIN_TEXT", content: feedback }, encodingType: "UTF16" },
  };
};

return [
  {
    json: prepare({
      response: $input.first().json,
      feedbackTitle: "Any suggestions for us?",
      nameTitle: "Name",
    }),
    pairedItem: { item: 0 },
  },
];

const validate = function readSentiment(inputs) {
  const body = inputs.body;
  const score = body?.documentSentiment?.score;
  if (
    !body ||
    typeof body !== "object" ||
    Array.isArray(body) ||
    body.error ||
    typeof score !== "number" ||
    !Number.isFinite(score) ||
    score < -1 ||
    score > 1
  )
    throw new Error("The sentiment service did not return a valid document score.");
  return { score };
};

return [{ json: validate({ body: $input.first().json }), pairedItem: { item: 0 } }];

const format = function prepareDestinations(inputs) {
  const { feedback, name, score } = inputs;
  if (
    typeof feedback !== "string" ||
    typeof name !== "string" ||
    typeof score !== "number" ||
    !Number.isFinite(score)
  )
    throw new Error("Expected feedback, name, and a sentiment score.");
  return {
    message: `You got a new feedback with a score of ${score}. Here is what it says:${feedback}`,
    properties: {
      Name: { title: [{ text: { content: name } }] },
      Feedback: { rich_text: [{ text: { content: feedback } }] },
    },
    attachments: [{ text: feedback, title: `${name} ${score}` }],
    cardName: `Score: ${score}`,
    cardDescription: `Score: ${score}\nFeedback: ${feedback}\nUser: ${name}`,
  };
};

return [
  {
    json: format({ ...$("Read Feedback Answers").first().json, score: $input.first().json.score }),
    pairedItem: { item: 0 },
  },
];
